/* From Uiverse.io by andrew-demchenk0 - Tags: alert, yellow, warning, card, message, close, warning message */
.__UIV_SCOPE__ .warning {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  width: 320px;
  padding: 12px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: start;
  background: #F7C752;
  border-radius: 8px;
  box-shadow: 0px 0px 5px -3px #111;
}

.__UIV_SCOPE__ .warning__icon {
  width: 20px;
  height: 20px;
  transform: translateY(-2px);
  margin-right: 8px;
}

.__UIV_SCOPE__ .warning__icon path {
  fill: #393A37;
}

.__UIV_SCOPE__ .warning__title {
  font-weight: 500;
  font-size: 14px;
  color: #393A37;
}

.__UIV_SCOPE__ .warning__close {
  width: 20px;
  height: 20px;
  margin-left: auto;
  cursor: pointer;
}

.__UIV_SCOPE__ .warning__close path {
  fill: #393A37;
}
